king_piece_tower.source:
export const envelope = [23, 64, 23];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 11;
  const cz = 11;
  const seatY = 6;

  // --- PALETTE DEFINITIONS ---
  const W_SMOOTH = "minecraft:smooth_quartz";
  const W_BRICK = api.theme.stone.accent || "minecraft:quartz_bricks";
  const W_PILLAR = "minecraft:quartz_pillar";
  const W_CHISELED = "minecraft:chiseled_quartz_block";
  const W_STAIRS = api.theme.stone.stairs || "minecraft:quartz_stairs";
  const W_SLAB = api.theme.stone.slab || "minecraft:quartz_slab";

  const B_POLISHED = api.theme.ground.plinth || "minecraft:polished_blackstone";
  const B_BRICK = "minecraft:polished_blackstone_bricks";
  const B_CHISELED = "minecraft:chiseled_polished_blackstone";
  const B_GILDED = "minecraft:gilded_blackstone";
  const B_STAIRS = "minecraft:polished_blackstone_stairs";
  const B_SLAB = "minecraft:polished_blackstone_slab";
  const B_WALL = api.theme.stone.wall || "minecraft:polished_blackstone_wall";

  const GOLD = "minecraft:gold_block";
  const LANTERN = "minecraft:sea_lantern";
  const TINTED = "minecraft:tinted_glass";
  const IRON_BARS = "minecraft:iron_bars";

  // Voxel storage grid for deterministic flushing
  const grid = new Map();

  function getIdx(x, y, z) {
    return (x << 16) | (y << 8) | z;
  }

  function setBlock(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    grid.set(getIdx(x, y, z), block);
  }

  function getBlock(x, y, z) {
    return grid.get(getIdx(x, y, z)) || null;
  }

  function removeBlock(x, y, z) {
    grid.delete(getIdx(x, y, z));
  }

  // Helper for directional stairs facing outward or inward
  function getOutwardStair(type, dx, dz, upsideDown = false) {
    let facing = "north";
    if (Math.abs(dx) >= Math.abs(dz)) {
      facing = dx > 0 ? "west" : "east";
    } else {
      facing = dz > 0 ? "north" : "south";
    }
    const half = upsideDown ? ",half=top" : ",half=bottom";
    const base = type === "white" ? W_STAIRS : B_STAIRS;
    return `${base}[facing=${facing}${half}]`;
  }

  function getInwardStair(type, dx, dz, upsideDown = false) {
    let facing = "south";
    if (Math.abs(dx) >= Math.abs(dz)) {
      facing = dx > 0 ? "east" : "west";
    } else {
      facing = dz > 0 ? "south" : "north";
    }
    const half = upsideDown ? ",half=top" : ",half=bottom";
    const base = type === "white" ? W_STAIRS : B_STAIRS;
    return `${base}[facing=${facing}${half}]`;
  }

  // Mathematical profile of the Staunton King Chess Piece
  function getRadius(ry) {
    if (ry <= 0) return 9.6;
    if (ry === 1) return 9.0;
    if (ry === 2) return 8.4;
    if (ry === 3) return 7.7;
    if (ry === 4) return 7.1;
    // Lower body frustum (5 to 18)
    if (ry >= 5 && ry <= 18) {
      const t = (ry - 5) / 13;
      return 6.9 - 2.4 * Math.sin(t * Math.PI * 0.5) + 0.1 * Math.sin(t * Math.PI);
    }
    // Mid waist ring / astragal (19 to 23)
    if (ry >= 19 && ry <= 23) {
      const t = (ry - 19) / 4;
      return 4.6 + 1.5 * Math.sin(t * Math.PI);
    }
    // Upper shaft / colonnade (24 to 34)
    if (ry >= 24 && ry <= 34) {
      const t = (ry - 24) / 10;
      return 4.4 - 0.2 * Math.sin(t * Math.PI) + 1.3 * (t * t);
    }
    // Necking & Collar (35 to 36)
    if (ry === 35) return 4.8;
    if (ry === 36) return 6.0;
    // Crown Chalice (37 to 41)
    if (ry >= 37 && ry <= 41) {
      const t = (ry - 37) / 4;
      return 5.2 + 2.2 * t;
    }
    // Crown Battlements (42 to 44)
    if (ry >= 42 && ry <= 44) {
      return 7.4;
    }
    return 0;
  }

  function getInnerRadius(ry) {
    if (ry >= 1 && ry <= 18) {
      const outR = getRadius(ry);
      return Math.max(0, outR - 1.45);
    }
    if (ry === 19) return 1.5; // Central mezzanine hatch
    if (ry >= 24 && ry <= 34) {
      const outR = getRadius(ry);
      return Math.max(0, outR - 1.35);
    }
    if (ry >= 37 && ry <= 41) {
      const outR = getRadius(ry);
      return Math.max(0, outR - 1.2);
    }
    return 0;
  }

  // --- 1. FOUNDATION, BASE PEDESTAL & CHECKERED APRON ---
  const maxFootprintR = 11.2;
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);
      if (dist > maxFootprintR) continue;

      const gh = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(seatY + 6, seatY + gh));
      const checker = ((Math.floor(x / 2) + Math.floor(z / 2)) % 2 === 0);

      // Apron around base (dist between 9.6 and 11.2)
      if (dist > 9.6) {
        for (let y = groundY; y >= Math.max(0, groundY - 1); y--) {
          const b = checker ? W_SMOOTH : B_POLISHED;
          setBlock(x, y, z, b);
        }
        continue;
      }

      // Base footprint: build foundation skirt down to terrain
      for (let y = seatY - 1; y >= groundY; y--) {
        const fBlock = ((Math.floor(x / 2) + Math.floor(z / 2) + y) % 2 === 0) ? B_BRICK : W_BRICK;
        setBlock(x, y, z, fBlock);
      }
      if (groundY > seatY) {
        for (let y = seatY; y <= groundY; y++) {
          const fBlock = ((Math.floor(x / 2) + Math.floor(z / 2) + y) % 2 === 0) ? B_BRICK : W_BRICK;
          setBlock(x, y, z, fBlock);
        }
      }
    }
  }

  // Plinth Steps (ry = 0 to 4)
  for (let ry = 0; ry <= 4; ry++) {
    const y = seatY + ry;
    const r = getRadius(ry);
    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist > r) continue;

        const isEdge = dist > r - 0.9;
        const checker = ((Math.floor(x / 2) + Math.floor(z / 2)) % 2 === 0);

        if (ry === 0) {
          if (isEdge) {
            setBlock(x, y, z, getOutwardStair(checker ? "white" : "black", dx, dz));
          } else {
            setBlock(x, y, z, checker ? W_SMOOTH : B_POLISHED);
          }
        } else if (ry === 1) {
          if (isEdge) {
            setBlock(x, y, z, checker ? B_BRICK : W_BRICK);
          } else {
            setBlock(x, y, z, checker ? W_SMOOTH : B_POLISHED);
          }
        } else if (ry === 2) {
          if (isEdge) {
            setBlock(x, y, z, checker ? W_CHISELED : B_CHISELED);
          } else {
            setBlock(x, y, z, checker ? W_SMOOTH : B_POLISHED);
          }
        } else if (ry === 3) {
          if (isEdge) {
            setBlock(x, y, z, getOutwardStair(checker ? "white" : "black", dx, dz, true));
          } else {
            setBlock(x, y, z, checker ? W_SMOOTH : B_POLISHED);
          }
        } else if (ry === 4) {
          setBlock(x, y, z, checker ? W_BRICK : B_BRICK);
        }
      }
    }
  }

  // 4 Corner Pawn Sentry Pedestals
  const cornerOffsets = [
    [-6.5, -6.5], [6.5, -6.5], [-6.5, 6.5], [6.5, 6.5]
  ];
  for (const [ox, oz] of cornerOffsets) {
    const px = Math.round(cx + ox);
    const pz = Math.round(cz + oz);
    for (let dx = -1; dx <= 0; dx++) {
      for (let dz = -1; dz <= 0; dz++) {
        const bx = px + dx;
        const bz = pz + dz;
        setBlock(bx, seatY + 1, bz, B_BRICK);
        setBlock(bx, seatY + 2, bz, W_PILLAR);
        setBlock(bx, seatY + 3, bz, B_GILDED);
      }
    }
    setBlock(px, seatY + 4, pz, LANTERN);
    setBlock(px - 1, seatY + 4, pz, B_WALL);
    setBlock(px, seatY + 4, pz - 1, B_WALL);
    setBlock(px - 1, seatY + 4, pz - 1, B_WALL);
  }

  // --- 2. MAIN TOWER BODY & COLONNADE (ry = 5 to 36) ---
  for (let ry = 5; ry <= 36; ry++) {
    const y = seatY + ry;
    const r = getRadius(ry);
    const inR = getInnerRadius(ry);

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist > r) continue;

        // Interior hollow
        if (dist < inR) {
          removeBlock(x, y, z);
          continue;
        }

        const angle = Math.atan2(dz, dx);
        const normAngle = (angle + 2 * Math.PI) % (2 * Math.PI);
        const sector = Math.floor(normAngle / (Math.PI / 4));
        const sectorFrac = (normAngle % (Math.PI / 4)) / (Math.PI / 4);
        const isRib = Math.abs(sectorFrac - 0.5) < 0.22;
        const ribType = sector % 2 === 0 ? "white" : "black";

        // Lower body (ry = 5 to 18)
        if (ry >= 5 && ry <= 18) {
          if (isRib) {
            if (ribType === "white") {
              setBlock(x, y, z, (ry === 5 || ry === 18) ? W_CHISELED : W_PILLAR);
            } else {
              setBlock(x, y, z, (ry === 5 || ry === 18) ? B_GILDED : B_BRICK);
            }
          } else {
            // Recessed wall panel
            const wallBlock = ribType === "white" ? B_POLISHED : W_SMOOTH;
            // Window slits on cardinal & ordinal midpoints
            if (dist > r - 0.9 && (ry === 8 || ry === 9 || ry === 14 || ry === 15)) {
              setBlock(x, y, z, TINTED);
            } else {
              setBlock(x, y, z, wallBlock);
            }
          }
        }
        // Mid waist ring (ry = 19 to 23)
        else if (ry >= 19 && ry <= 23) {
          if (ry === 19) {
            // Mid floor
            if (dist < 1.6) {
              removeBlock(x, y, z);
            } else {
              const checker = ((Math.floor(x / 2) + Math.floor(z / 2)) % 2 === 0);
              setBlock(x, y, z, checker ? W_SMOOTH : B_POLISHED);
            }
          } else if (ry === 20 || ry === 21) {
            if (dist > r - 0.8) {
              setBlock(x, y, z, isRib ? (ribType === "white" ? GOLD : LANTERN) : (ribType === "white" ? B_GILDED : W_CHISELED));
            } else {
              setBlock(x, y, z, ribType === "white" ? W_BRICK : B_BRICK);
            }
          } else {
            setBlock(x, y, z, ribType === "white" ? W_SMOOTH : B_POLISHED);
          }
        }
        // Upper Colonnade & Shaft (ry = 24 to 34)
        else if (ry >= 24 && ry <= 34) {
          if (ry === 24) {
            // High chamber floor
            const checker = ((Math.floor(x / 2) + Math.floor(z / 2)) % 2 === 0);
            setBlock(x, y, z, checker ? W_SMOOTH : B_POLISHED);
          } else {
            // Colonnade pillars vs open windows
            if (isRib) {
              if (ribType === "white") {
                setBlock(x, y, z, ry === 34 ? W_CHISELED : W_PILLAR);
              } else {
                setBlock(x, y, z, ry === 34 ? B_GILDED : B_BRICK);
              }
            } else {
              // Open arches between columns
              if (ry >= 26 && ry <= 31) {
                removeBlock(x, y, z);
              } else if (ry === 32) {
                setBlock(x, y, z, getOutwardStair(ribType === "white" ? "black" : "white", dx, dz, true));
              } else {
                setBlock(x, y, z, ribType === "white" ? B_POLISHED : W_SMOOTH);
              }
            }
          }
        }
        // Necking & Collar (ry = 35 to 36)
        else if (ry === 35) {
          setBlock(x, y, z, ribType === "white" ? B_BRICK : W_BRICK);
        } else if (ry === 36) {
          if (dist > r - 0.9) {
            setBlock(x, y, z, getOutwardStair(ribType === "white" ? "white" : "black", dx, dz, true));
          } else {
            setBlock(x, y, z, ribType === "white" ? W_CHISELED : B_GILDED);
          }
        }
      }
    }
  }

  // --- 3. THE KING'S CROWN / CORONET & PROMENADE (ry = 37 to 44) ---
  for (let ry = 37; ry <= 44; ry++) {
    const y = seatY + ry;
    const r = getRadius(ry);
    const inR = getInnerRadius(ry);

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist > r) continue;

        const angle = Math.atan2(dz, dx);
        const normAngle = (angle + 2 * Math.PI) % (2 * Math.PI);
        const sector = Math.floor(normAngle / (Math.PI / 4));
        const sectorFrac = (normAngle % (Math.PI / 4)) / (Math.PI / 4);
        const isPeak = Math.abs(sectorFrac - 0.5) < 0.2;
        const checker = (sector % 2 === 0);

        if (ry <= 41) {
          // Chalice bowl shell
          if (dist >= inR) {
            setBlock(x, y, z, checker ? W_SMOOTH : B_POLISHED);
          } else if (ry === 41) {
            // Crown promenade deck
            setBlock(x, y, z, checker ? W_BRICK : B_BRICK);
          } else {
            removeBlock(x, y, z);
          }
        } else {
          // ry = 42 to 44: 8 Crown Peaks vs Parapet
          if (dist > r - 1.2) {
            if (isPeak) {
              if (ry === 42) {
                setBlock(x, y, z, checker ? W_CHISELED : B_GILDED);
              } else if (ry === 43) {
                setBlock(x, y, z, checker ? GOLD : LANTERN);
              } else if (ry === 44) {
                setBlock(x, y, z, checker ? B_WALL : GOLD);
              }
            } else {
              if (ry === 42) {
                setBlock(x, y, z, checker ? W_SLAB : B_SLAB);
              } else {
                removeBlock(x, y, z);
              }
            }
          }
        }
      }
    }
  }

  // --- 4. THE GLOBUS / DOME (ry = 42 to 46) ---
  for (let dy = 0; dy <= 4; dy++) {
    const ry = 42 + dy;
    const y = seatY + ry;
    const domeR = Math.sqrt(Math.max(0, 16 - (dy * dy) * 1.0));

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist > domeR) continue;

        const isMeridian = (Math.abs(dx) <= 0.6 || Math.abs(dz) <= 0.6);
        if (dy === 4) {
          setBlock(x, y, z, GOLD);
        } else if (isMeridian) {
          setBlock(x, y, z, B_GILDED);
        } else {
          setBlock(x, y, z, W_SMOOTH);
        }
      }
    }
  }

  // --- 5. THE ROYAL CROSS FINIAL (ry = 46 to 53) ---
  // ry = 46: Cross Plinth
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      setBlock(cx + dx, seatY + 46, cz + dz, (dx === 0 || dz === 0) ? GOLD : B_GILDED);
    }
  }

  // ry = 47, 48: Lower Cross Stem
  for (let y = seatY + 47; y <= seatY + 48; y++) {
    setBlock(cx, y, cz, B_GILDED);
    setBlock(cx + 1, y, cz, `${W_STAIRS}[facing=east,half=bottom]`);
    setBlock(cx - 1, y, cz, `${W_STAIRS}[facing=west,half=bottom]`);
    setBlock(cx, y, cz + 1, `${W_STAIRS}[facing=south,half=bottom]`);
    setBlock(cx, y, cz - 1, `${W_STAIRS}[facing=north,half=bottom]`);
  }

  // ry = 49, 50: Cross Arms & Heart
  const crossY1 = seatY + 49;
  const crossY2 = seatY + 50;

  // Glowing heart
  setBlock(cx, crossY1, cz, LANTERN);
  setBlock(cx, crossY2, cz, B_GILDED);
  setBlock(cx, crossY1, cz - 1, B_GILDED);
  setBlock(cx, crossY1, cz + 1, B_GILDED);

  // Horizontal arms along X axis
  for (let armX = cx - 3; armX <= cx + 3; armX++) {
    if (armX === cx) continue;
    const distFromCenter = Math.abs(armX - cx);

    if (distFromCenter === 1) {
      setBlock(armX, crossY1, cz, B_GILDED);
      setBlock(armX, crossY2, cz, B_SLAB);
    } else if (distFromCenter === 2) {
      setBlock(armX, crossY1, cz, B_POLISHED);
      setBlock(armX, crossY2, cz, W_SLAB);
    } else if (distFromCenter === 3) {
      // Floriated arm terminals
      setBlock(armX, crossY1, cz, GOLD);
      const stairFacing = armX > cx ? "west" : "east";
      setBlock(armX, crossY2, cz, `${W_STAIRS}[facing=${stairFacing},half=bottom]`);
      setBlock(armX, crossY1 - 1, cz, `${W_STAIRS}[facing=${stairFacing},half=top]`);
    }
  }

  // ry = 51 to 53: Upper Cross Spire & Terminal
  setBlock(cx, seatY + 51, cz, B_POLISHED);
  setBlock(cx + 1, seatY + 51, cz, `${W_STAIRS}[facing=west,half=top]`);
  setBlock(cx - 1, seatY + 51, cz, `${W_STAIRS}[facing=east,half=top]`);

  setBlock(cx, seatY + 52, cz, GOLD);
  setBlock(cx + 1, seatY + 52, cz, `${W_STAIRS}[facing=east,half=bottom]`);
  setBlock(cx - 1, seatY + 52, cz, `${W_STAIRS}[facing=west,half=bottom]`);
  setBlock(cx, seatY + 52, cz + 1, `${W_STAIRS}[facing=south,half=bottom]`);
  setBlock(cx, seatY + 52, cz - 1, `${W_STAIRS}[facing=north,half=bottom]`);

  setBlock(cx, seatY + 53, cz, B_WALL);

  // --- 6. PORTALS & STAIRWAYS ---
  // North Entrance Gate (Local North -Z)
  for (let z = cz - 8; z <= cz - 4; z++) {
    for (let x = cx - 1; x <= cx + 1; x++) {
      for (let y = seatY + 1; y <= seatY + 5; y++) {
        removeBlock(x, y, z);
      }
    }
  }
  // North Portal Grand Frame
  for (let y = seatY + 1; y <= seatY + 5; y++) {
    setBlock(cx - 2, y, cz - 6, (y === seatY + 5) ? B_GILDED : W_PILLAR);
    setBlock(cx + 2, y, cz - 6, (y === seatY + 5) ? B_GILDED : W_PILLAR);
  }
  setBlock(cx - 1, seatY + 6, cz - 6, `${B_STAIRS}[facing=east,half=bottom]`);
  setBlock(cx + 1, seatY + 6, cz - 6, `${B_STAIRS}[facing=west,half=bottom]`);
  setBlock(cx, seatY + 6, cz - 6, B_GILDED);
  setBlock(cx, seatY + 7, cz - 6, LANTERN);

  // Grand Steps in front of North Gate adapting to terrain
  for (let step = 1; step <= 3; step++) {
    const curZ = cz - 6 - step;
    const targetY = seatY + 1 - step;
    for (let x = cx - 2; x <= cx + 2; x++) {
      const curGH = api.heightAt(x, curZ);
      const curGround = Math.max(0, seatY + curGH);
      const stairY = Math.max(curGround, targetY);

      setBlock(x, stairY, curZ, `${W_STAIRS}[facing=south,half=bottom]`);
      for (let fy = stairY - 1; fy >= curGround; fy--) {
        setBlock(x, fy, curZ, B_BRICK);
      }
    }
  }

  // South Balcony Window (Local South +Z)
  for (let z = cz + 4; z <= cz + 7; z++) {
    for (let x = cx - 1; x <= cx + 1; x++) {
      for (let y = seatY + 2; y <= seatY + 5; y++) {
        removeBlock(x, y, z);
      }
    }
  }
  setBlock(cx - 1, seatY + 2, cz + 6, B_WALL);
  setBlock(cx, seatY + 2, cz + 6, B_WALL);
  setBlock(cx + 1, seatY + 2, cz + 6, B_WALL);

  // Interior Spiral Stairway hugging inner wall in Hall
  for (let step = 0; step < 18; step++) {
    const stairY = seatY + 1 + step;
    const angle = step * (Math.PI / 4.0);
    const sx = Math.round(cx + 3.0 * Math.cos(angle));
    const sz = Math.round(cz + 3.0 * Math.sin(angle));
    setBlock(sx, stairY, sz, `${W_STAIRS}[facing=north,half=bottom]`);
    if (stairY > seatY + 1) {
      setBlock(sx, stairY - 1, sz, B_BRICK);
    }
  }

  // --- 7. FLUSH TO OUTPUT STREAM ---
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const b = getBlock(x, y, z);
        if (b !== null) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "King's Spire Monument",
    seatY: seatY,
    anchors: {
      front: [cx, seatY + 1, 0],
      door: [cx, seatY + 1, cz - 7],
      crown: [cx, seatY + 41, cz],
      cross: [cx, seatY + 53, cz]
    },
    interiors: [
      {
        min: [cx - 3, seatY + 1, cz - 3],
        max: [cx + 3, seatY + 18, cz + 3],
        kind: "hall"
      },
      {
        min: [cx - 2, seatY + 24, cz - 2],
        max: [cx + 2, seatY + 33, cz + 2],
        kind: "vault"
      }
    ]
  };
}

knight_piece_statue.source:
export const envelope = [15, 30, 17];

export default function build(api) {
  const { size } = api;
  const seatY = 4;

  // Extract theme materials with fallbacks to classical black & white marble
  const W_PRIMARY = api.theme?.stone?.primary || "minecraft:smooth_quartz";
  const W_ACCENT = api.theme?.stone?.accent || "minecraft:quartz_bricks";
  const W_STAIRS = api.theme?.stone?.stairs || "minecraft:quartz_stairs";
  const W_SLAB = api.theme?.stone?.slab || "minecraft:quartz_slab";
  const W_PILLAR = "minecraft:quartz_pillar";
  const W_CALCITE = "minecraft:calcite";

  const B_PRIMARY = "minecraft:polished_blackstone";
  const B_ACCENT = "minecraft:polished_blackstone_bricks";
  const B_STAIRS = "minecraft:polished_blackstone_stairs";
  const B_SLAB = "minecraft:polished_blackstone_slab";
  const B_WALL = "minecraft:polished_blackstone_wall";
  const B_GILDED = "minecraft:gilded_blackstone";

  const PLINTH_BASE = api.theme?.ground?.plinth || "minecraft:polished_blackstone";
  const PLINTH_REVETMENT = api.theme?.ground?.revetment || "minecraft:polished_blackstone_bricks";

  function makeStair(baseStair, facing, half = "bottom", shape = "straight") {
    const clean = baseStair.split("[")[0];
    return `${clean}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function makeSlab(baseSlab, type = "bottom") {
    const clean = baseSlab.split("[")[0];
    return `${clean}[type=${type}]`;
  }

  // 3D placement buffer: [Y][X][Z]
  const grid = Array.from({ length: size[1] }, () =>
    Array.from({ length: size[0] }, () => Array(size[2]).fill(null))
  );

  function put(x, y, z, block, overwrite = true) {
    if (x >= 0 && x < size[0] && y >= 0 && y < size[1] && z >= 0 && z < size[2]) {
      if (overwrite || grid[y][x][z] === null) {
        grid[y][x][z] = block;
      }
    }
  }

  // --- 1. Plinth Base (ry = 0): Monumental Chessboard Pattern ---
  for (let x = 1; x <= 13; x++) {
    for (let z = 2; z <= 14; z++) {
      const dx = Math.abs(x - 7);
      const dz = Math.abs(z - 8);
      if (dx <= 6 && dz <= 6 && dx + dz <= 9) {
        const isStairNorthSouth = (dz === 6 && dx <= 3);
        const isStairEastWest = (dx === 6 && dz <= 3);
        const isBorder = (dx === 6 || dz === 6 || dx + dz === 9);

        if (isStairNorthSouth) {
          put(x, seatY + 0, z, makeStair(B_STAIRS, z < 8 ? "north" : "south"));
        } else if (isStairEastWest) {
          put(x, seatY + 0, z, makeStair(B_STAIRS, x < 7 ? "west" : "east"));
        } else if (isBorder) {
          put(x, seatY + 0, z, B_PRIMARY);
        } else {
          put(x, seatY + 0, z, (x + z) % 2 === 0 ? W_PRIMARY : B_PRIMARY);
        }
      }
    }
  }

  // --- 2. Plinth Step 1 (ry = 1) ---
  for (let x = 2; x <= 12; x++) {
    for (let z = 3; z <= 13; z++) {
      const dx = Math.abs(x - 7);
      const dz = Math.abs(z - 8);
      if (dx <= 5 && dz <= 5 && dx + dz <= 7) {
        const isStairNS = (dz === 5 && dx <= 2);
        const isStairEW = (dx === 5 && dz <= 2);
        const isBorder = (dx === 5 || dz === 5 || dx + dz === 7);

        if (isStairNS) {
          put(x, seatY + 1, z, makeStair(B_STAIRS, z < 8 ? "north" : "south"));
        } else if (isStairEW) {
          put(x, seatY + 1, z, makeStair(B_STAIRS, x < 7 ? "west" : "east"));
        } else if (isBorder) {
          put(x, seatY + 1, z, B_PRIMARY);
        } else {
          put(x, seatY + 1, z, (x + z) % 2 === 0 ? W_ACCENT : B_ACCENT);
        }
      }
    }
  }

  // --- 3. Pedestal Dado / Inset Shaft (ry = 2) ---
  for (let x = 3; x <= 11; x++) {
    for (let z = 4; z <= 12; z++) {
      const dx = Math.abs(x - 7);
      const dz = Math.abs(z - 8);
      if (dx <= 4 && dz <= 4 && dx + dz <= 6) {
        const isCorner = (dx === 4 && dz >= 2) || (dz === 4 && dx >= 2) || (dx + dz === 6);
        if (isCorner) {
          put(x, seatY + 2, z, B_ACCENT);
        } else if ((z === 4 || z === 12) && dx <= 1) {
          put(x, seatY + 2, z, dx === 0 ? W_CALCITE : `${W_PILLAR}[axis=y]`);
        } else if ((x === 3 || x === 11) && dz <= 1) {
          put(x, seatY + 2, z, dz === 0 ? W_CALCITE : `${W_PILLAR}[axis=y]`);
        } else {
          put(x, seatY + 2, z, W_PRIMARY);
        }
      }
    }
  }

  // --- 4. Pedestal Cornice (ry = 3): Flaring Inverted Capital ---
  for (let x = 2; x <= 12; x++) {
    for (let z = 3; z <= 13; z++) {
      const dx = Math.abs(x - 7);
      const dz = Math.abs(z - 8);
      if (dx <= 5 && dz <= 5 && dx + dz <= 7) {
        const isStairNS = (dz === 5 && dx <= 2);
        const isStairEW = (dx === 5 && dz <= 2);
        if (isStairNS) {
          put(x, seatY + 3, z, makeStair(B_STAIRS, z < 8 ? "south" : "north", "top"));
        } else if (isStairEW) {
          put(x, seatY + 3, z, makeStair(B_STAIRS, x < 7 ? "east" : "west", "top"));
        } else if (dx === 4 || dz === 4 || dx + dz === 7) {
          put(x, seatY + 3, z, B_PRIMARY);
        } else {
          put(x, seatY + 3, z, B_ACCENT);
        }
      }
    }
  }

  // --- 5. Plinth Top Turntable Disc (ry = 4) ---
  for (let x = 3; x <= 11; x++) {
    for (let z = 4; z <= 12; z++) {
      const dx = Math.abs(x - 7);
      const dz = Math.abs(z - 8);
      const distSq = dx * dx + dz * dz;
      if (distSq <= 19) {
        if (distSq >= 13) {
          put(x, seatY + 4, z, makeSlab(B_SLAB, "bottom"));
        } else if (dx === 0 && dz === 0) {
          put(x, seatY + 4, z, B_GILDED);
        } else {
          put(x, seatY + 4, z, (x + z) % 2 === 0 ? W_PRIMARY : B_PRIMARY);
        }
      }
    }
  }

  // --- 6. Chess Piece Base Torus (ry = 5) ---
  for (let x = 4; x <= 10; x++) {
    for (let z = 5; z <= 11; z++) {
      const dx = Math.abs(x - 7);
      const dz = Math.abs(z - 8);
      const distSq = dx * dx + dz * dz;
      if (distSq <= 13) {
        if (dz >= 3 && dx <= 1) {
          put(x, seatY + 5, z, makeStair(W_STAIRS, z < 8 ? "north" : "south"));
        } else if (dx >= 3 && dz <= 1) {
          put(x, seatY + 5, z, makeStair(W_STAIRS, x < 7 ? "west" : "east"));
        } else {
          put(x, seatY + 5, z, W_PRIMARY);
        }
      }
    }
  }

  // --- 7. Narrowed Collar Ring (ry = 6) ---
  for (let x = 4; x <= 10; x++) {
    for (let z = 5; z <= 11; z++) {
      const dx = Math.abs(x - 7);
      const dz = Math.abs(z - 8);
      const distSq = dx * dx + dz * dz;
      if (distSq <= 8) {
        put(x, seatY + 6, z, distSq >= 5 ? B_PRIMARY : W_PRIMARY);
      }
    }
  }

  // --- 8. Torso & Chest Root (ry = 7) ---
  for (let x = 5; x <= 9; x++) {
    for (let z = 5; z <= 11; z++) {
      const dx = Math.abs(x - 7);
      if (z === 5 && dx <= 1) {
        put(x, seatY + 7, z, makeStair(W_STAIRS, "north"));
      } else if (z === 11 && dx <= 1) {
        put(x, seatY + 7, z, B_PRIMARY);
      } else {
        put(x, seatY + 7, z, W_PRIMARY);
      }
    }
  }

  // --- 9. Chest & Dorsal Spine Base (ry = 8) ---
  for (let x = 4; x <= 10; x++) {
    for (let z = 4; z <= 12; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z <= 5 && dx <= 2) || (z >= 6 && z <= 10 && dx <= 3) || (z >= 11 && dx <= 1);
      if (inBody) {
        if (z === 4 && dx <= 1) {
          put(x, seatY + 8, z, makeStair(W_STAIRS, "north"));
        } else if (z === 12 && dx <= 1) {
          put(x, seatY + 8, z, B_PRIMARY);
        } else {
          put(x, seatY + 8, z, W_PRIMARY);
        }
      }
    }
  }
  put(7, seatY + 8, 13, makeStair(B_STAIRS, "south"));

  // --- 10. Powerful Bulging Breast & Mane Lock 1 (ry = 9) ---
  for (let x = 4; x <= 10; x++) {
    for (let z = 3; z <= 12; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z === 3 && dx <= 1) || (z >= 4 && z <= 5 && dx <= 2) ||
                     (z >= 6 && z <= 9 && dx <= 3) || (z >= 10 && z <= 11 && dx <= 2) ||
                     (z === 12 && dx <= 1);
      if (inBody) {
        if (z === 3 && dx <= 1) {
          put(x, seatY + 9, z, makeStair(W_STAIRS, "north"));
        } else if (dx === 3 && z >= 6 && z <= 8) {
          put(x, seatY + 9, z, makeStair(W_STAIRS, x === 4 ? "west" : "east"));
        } else if (z === 12 && dx <= 1) {
          put(x, seatY + 9, z, B_PRIMARY);
        } else {
          put(x, seatY + 9, z, W_PRIMARY);
        }
      }
    }
  }
  put(7, seatY + 9, 13, B_ACCENT);

  // --- 11. Mid Rearing Chest & Mane Lock 2 (ry = 10) ---
  for (let x = 4; x <= 10; x++) {
    for (let z = 3; z <= 12; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z === 3 && dx <= 2) || (z >= 4 && z <= 9 && dx <= 3) ||
                     (z >= 10 && z <= 11 && dx <= 2) || (z === 12 && dx <= 1);
      if (inBody) {
        if (z === 3 && dx <= 1) {
          put(x, seatY + 10, z, makeStair(W_STAIRS, "north"));
        } else if (dx === 3 && z >= 5 && z <= 7) {
          put(x, seatY + 10, z, makeStair(W_STAIRS, x === 4 ? "west" : "east"));
        } else if (z === 12 && dx <= 1) {
          put(x, seatY + 10, z, B_PRIMARY);
        } else {
          put(x, seatY + 10, z, W_PRIMARY);
        }
      }
    }
  }
  put(7, seatY + 10, 13, makeStair(B_STAIRS, "south"));

  // --- 12. Foremost Chest Peak with Medallion (ry = 11) ---
  for (let x = 4; x <= 10; x++) {
    for (let z = 2; z <= 12; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z === 2 && dx <= 1) || (z === 3 && dx <= 2) ||
                     (z >= 4 && z <= 8 && dx <= 3) || (z >= 9 && z <= 10 && dx <= 2) ||
                     (z >= 11 && z <= 12 && dx <= 1);
      if (inBody) {
        if (z === 2) {
          put(x, seatY + 11, z, dx === 0 ? B_GILDED : makeStair(W_STAIRS, "north"));
        } else if (z >= 11 && dx <= 1) {
          put(x, seatY + 11, z, B_PRIMARY);
        } else {
          put(x, seatY + 11, z, W_PRIMARY);
        }
      }
    }
  }
  put(7, seatY + 11, 13, makeSlab(B_SLAB, "bottom"));

  // --- 13. Upper Chest & Neck Incline (ry = 12) ---
  for (let x = 4; x <= 10; x++) {
    for (let z = 3; z <= 11; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z === 3 && dx <= 2) || (z >= 4 && z <= 8 && dx <= 3) ||
                     (z >= 9 && z <= 10 && dx <= 2) || (z === 11 && dx <= 1);
      if (inBody) {
        if (z === 3 && dx <= 1) {
          put(x, seatY + 12, z, makeStair(W_STAIRS, "north"));
        } else if (z === 11 && dx <= 1) {
          put(x, seatY + 12, z, B_PRIMARY);
        } else {
          put(x, seatY + 12, z, W_PRIMARY);
        }
      }
    }
  }
  put(7, seatY + 12, 12, B_PRIMARY);

  // --- 14. Throat Arch & Jaw Underside (ry = 13) ---
  for (let x = 5; x <= 9; x++) {
    for (let z = 2; z <= 10; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z === 2 && dx <= 1) || (z >= 3 && z <= 7 && dx <= 2) ||
                     (z >= 8 && z <= 9 && dx <= 2) || (z === 10 && dx <= 1);
      if (inBody) {
        if (z === 2 && dx <= 1) {
          put(x, seatY + 13, z, makeStair(W_STAIRS, "north", "top"));
        } else if (z === 10 && dx <= 1) {
          put(x, seatY + 13, z, B_PRIMARY);
        } else {
          put(x, seatY + 13, z, W_PRIMARY);
        }
      }
    }
  }
  put(7, seatY + 13, 11, B_PRIMARY);
  put(7, seatY + 13, 12, makeStair(B_STAIRS, "south"));

  // --- 15. Chin, Lower Jaw & Sculpted Ganache (ry = 14) ---
  for (let x = 4; x <= 10; x++) {
    for (let z = 1; z <= 10; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z === 1 && dx <= 1) || (z >= 2 && z <= 3 && dx <= 2) ||
                     (z >= 4 && z <= 7 && dx <= 3) || (z >= 8 && z <= 9 && dx <= 2) ||
                     (z === 10 && dx <= 1);
      if (inBody) {
        if (z === 1 && dx <= 1) {
          put(x, seatY + 14, z, makeStair(W_STAIRS, "north"));
        } else if (dx === 3 && z >= 4 && z <= 6) {
          put(x, seatY + 14, z, makeStair(W_STAIRS, x === 4 ? "west" : "east", "top"));
        } else if (z === 10 && dx <= 1) {
          put(x, seatY + 14, z, B_PRIMARY);
        } else {
          put(x, seatY + 14, z, W_PRIMARY);
        }
      }
    }
  }
  put(7, seatY + 14, 11, B_PRIMARY);

  // --- 16. Muzzle, Bridle Straps & Medallions (ry = 15) ---
  for (let x = 4; x <= 10; x++) {
    for (let z = 1; z <= 10; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z === 1 && dx <= 1) || (z === 2 && dx <= 2) ||
                     (z >= 3 && z <= 7 && dx <= 3) || (z === 8 && dx <= 2) ||
                     (z >= 9 && z <= 10 && dx <= 1);
      if (inBody) {
        if (z === 2 && dx === 2) {
          put(x, seatY + 15, z, B_PRIMARY); // Bridle strap
        } else if (dx === 3 && z === 5) {
          put(x, seatY + 15, z, B_GILDED);  // Cheek rosette medallion
        } else if (dx === 3 && (z === 4 || z === 6)) {
          put(x, seatY + 15, z, makeStair(W_STAIRS, x === 4 ? "west" : "east"));
        } else if (z >= 9 && dx <= 1) {
          put(x, seatY + 15, z, B_PRIMARY);
        } else {
          put(x, seatY + 15, z, W_PRIMARY);
        }
      }
    }
  }
  put(7, seatY + 15, 11, makeStair(B_STAIRS, "south"));

  // --- 17. Nostrils & Nose Bridge (ry = 16) ---
  for (let x = 4; x <= 10; x++) {
    for (let z = 1; z <= 9; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z === 1 && dx <= 2) || (z >= 2 && z <= 3 && dx <= 2) ||
                     (z >= 4 && z <= 7 && dx <= 3) || (z === 8 && dx <= 2) ||
                     (z === 9 && dx <= 1);
      if (inBody) {
        if (z === 1) {
          if (dx === 0) put(x, seatY + 16, z, W_PRIMARY);
          else if (dx === 1) put(x, seatY + 16, z, B_PRIMARY); // Flared nostril socket
          else put(x, seatY + 16, z, makeStair(W_STAIRS, x === 5 ? "west" : "east"));
        } else if (z >= 2 && z <= 3 && dx === 2) {
          put(x, seatY + 16, z, B_PRIMARY); // Bridle side strap
        } else if (dx === 3 && (z === 5 || z === 6)) {
          put(x, seatY + 16, z, makeStair(W_STAIRS, x === 4 ? "west" : "east"));
        } else if (z === 9 && dx <= 1) {
          put(x, seatY + 16, z, B_PRIMARY);
        } else {
          put(x, seatY + 16, z, W_PRIMARY);
        }
      }
    }
  }
  put(7, seatY + 16, 10, B_PRIMARY);

  // --- 18. Eyes & Eyebrow Arches (ry = 17) ---
  for (let x = 4; x <= 10; x++) {
    for (let z = 2; z <= 9; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z === 2 && dx <= 1) || (z >= 3 && z <= 4 && dx <= 2) ||
                     (z === 5 && dx <= 3) || (z >= 6 && z <= 7 && dx <= 3) ||
                     (z === 8 && dx <= 2) || (z === 9 && dx <= 1);
      if (inBody) {
        if (z === 2 && dx <= 1) {
          put(x, seatY + 17, z, makeStair(W_STAIRS, "north"));
        } else if (z === 5 && dx === 2) {
          put(x, seatY + 17, z, B_GILDED); // Luminous carved eyes!
        } else if (z === 5 && dx === 3) {
          put(x, seatY + 17, z, makeStair(W_STAIRS, x === 4 ? "west" : "east", "top")); // Eyebrow arch
        } else if (z >= 3 && z <= 4 && dx === 2) {
          put(x, seatY + 17, z, B_PRIMARY); // Bridle band
        } else if (z === 5 && dx === 0) {
          put(x, seatY + 17, z, W_CALCITE); // Forehead star
        } else if (z === 9 && dx <= 1) {
          put(x, seatY + 17, z, B_PRIMARY);
        } else {
          put(x, seatY + 17, z, W_PRIMARY);
        }
      }
    }
  }
  put(7, seatY + 17, 10, makeStair(B_STAIRS, "south"));

  // --- 19. Sloping Forehead & Brow (ry = 18) ---
  for (let x = 5; x <= 9; x++) {
    for (let z = 3; z <= 9; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z === 3 && dx <= 1) || (z >= 4 && z <= 7 && dx <= 2) ||
                     (z === 8 && dx <= 1) || (z === 9 && dx === 0);
      if (inBody) {
        if (z === 3 && dx <= 1) {
          put(x, seatY + 18, z, makeStair(W_STAIRS, "north"));
        } else if ((z === 4 || z === 5) && dx === 0) {
          put(x, seatY + 18, z, W_CALCITE);
        } else if ((z === 6 || z === 7) && dx === 2) {
          put(x, seatY + 18, z, B_PRIMARY);
        } else if (z >= 8) {
          put(x, seatY + 18, z, B_PRIMARY);
        } else {
          put(x, seatY + 18, z, W_PRIMARY);
        }
      }
    }
  }

  // --- 20. Skull Top & Poll (ry = 19) ---
  for (let x = 5; x <= 9; x++) {
    for (let z = 4; z <= 9; z++) {
      const dx = Math.abs(x - 7);
      const inBody = (z === 4 && dx === 0) || (z >= 5 && z <= 7 && dx <= 2) ||
                     (z === 8 && dx <= 1) || (z === 9 && dx === 0);
      if (inBody) {
        if (z === 4 && dx === 0) {
          put(x, seatY + 19, z, makeStair(W_STAIRS, "north"));
        } else if (z === 9 && dx === 0) {
          put(x, seatY + 19, z, makeStair(B_STAIRS, "south"));
        } else if (z === 8) {
          put(x, seatY + 19, z, B_PRIMARY);
        } else {
          put(x, seatY + 19, z, W_PRIMARY);
        }
      }
    }
  }

  // --- 21. Forelock Tuft & Ear Roots (ry = 20) ---
  put(7, seatY + 20, 5, makeStair(W_STAIRS, "north")); // Forelock lock
  put(6, seatY + 20, 6, W_PRIMARY);
  put(7, seatY + 20, 6, W_PRIMARY);
  put(8, seatY + 20, 6, W_PRIMARY);
  // Left Ear root
  put(5, seatY + 20, 6, makeStair(W_STAIRS, "north"));
  put(5, seatY + 20, 7, W_PRIMARY);
  // Right Ear root
  put(9, seatY + 20, 6, makeStair(W_STAIRS, "north"));
  put(9, seatY + 20, 7, W_PRIMARY);
  // Mane top
  put(7, seatY + 20, 8, B_PRIMARY);

  // --- 22. Lower Ears & Forelock Crest (ry = 21) ---
  put(7, seatY + 21, 5, makeSlab(W_SLAB, "bottom"));
  put(7, seatY + 21, 6, makeSlab(W_SLAB, "bottom"));
  // Left ear
  put(5, seatY + 21, 6, makeStair(W_STAIRS, "north"));
  put(5, seatY + 21, 7, W_PRIMARY);
  // Right ear
  put(9, seatY + 21, 6, makeStair(W_STAIRS, "north"));
  put(9, seatY + 21, 7, W_PRIMARY);
  // Mane apex spike
  put(7, seatY + 21, 8, makeStair(B_STAIRS, "south"));

  // --- 23. Upright Alert Ears (ry = 22) ---
  put(5, seatY + 22, 6, makeStair(W_STAIRS, "south"));
  put(5, seatY + 22, 7, W_PRIMARY);
  put(9, seatY + 22, 6, makeStair(W_STAIRS, "south"));
  put(9, seatY + 22, 7, W_PRIMARY);

  // --- 24. Upper Ear Points (ry = 23) ---
  put(5, seatY + 23, 7, makeStair(W_STAIRS, "north"));
  put(9, seatY + 23, 7, makeStair(W_STAIRS, "north"));

  // --- 25. Ear Finials (ry = 24) ---
  put(5, seatY + 24, 7, B_WALL);
  put(9, seatY + 24, 7, B_WALL);

  // --- Terrain Ground Conformance (Rule 6) ---
  // For every occupied column on the ground plane, ensure foundation reaches real ground.
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      if (grid[seatY][x][z] !== null) {
        const gh = Math.round(api.heightAt(x, z));
        const groundY = Math.max(0, seatY + gh);
        if (groundY < seatY) {
          for (let y = groundY; y < seatY; y++) {
            const isWhite = (x + z) % 2 === 0;
            put(x, y, z, isWhite ? PLINTH_BASE : PLINTH_REVETMENT);
          }
        }
      }
    }
  }

  // --- Write buffered voxels to the world ---
  for (let y = 0; y < size[1]; y++) {
    for (let x = 0; x < size[0]; x++) {
      for (let z = 0; z < size[2]; z++) {
        if (grid[y][x][z] !== null) {
          api.set(x, y, z, grid[y][x][z]);
        }
      }
    }
  }

  return {
    name: "knight_piece_statue",
    seatY: seatY,
    anchors: {
      front: [7, seatY, 0],
      base: [7, seatY, 8],
    },
  };
}
